import { createContext, useContext, useState } from 'react';

// 1. Create the context
const ThemeContext = createContext({
  theme: 'dark',
  toggleTheme: () => {}
});

// 2. Create a provider component with the state
export function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('dark');
  const toggleTheme = () => setTheme(t => t === 'dark' ? 'light' : 'dark');

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

// 3. Custom hook for clean usage
export function useTheme() {
  const context = useContext(ThemeContext);
  if (!context) throw new Error('useTheme must be used within ThemeProvider');
  return context;
}

// 4. Consume anywhere in the tree — no prop drilling
function ThemeToggle() {
  const { theme, toggleTheme } = useTheme();
  return (
    <button onClick={toggleTheme}>
      Switch to {theme === 'dark' ? 'light' : 'dark'} mode
    </button>
  );
}

import { BrowserRouter, Routes, Route, Link, NavLink,
         useParams, useNavigate, useSearchParams, Outlet } from 'react-router-dom';

// App setup
export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Layout />}>
          <Route index element={<Home />} />
          <Route path="courses" element={<CourseList />} />
          <Route path="courses/:courseId" element={<CourseDetail />} />
          <Route path="courses/:courseId/lessons/:lessonId" element={<Lesson />} />
          <Route path="*" element={<NotFound />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}

// Layout with Outlet
function Layout() {
  return (
    <>
      <nav>
        <NavLink to="/" end className={({ isActive }) => isActive ? 'active' : ''}>
          Home
        </NavLink>
        <NavLink to="/courses">Courses</NavLink>
      </nav>
      <Outlet /> {/* renders matched child route */}
    </>
  );
}

// Route with params
function CourseDetail() {
  const { courseId } = useParams();
  const navigate = useNavigate();
  const [search] = useSearchParams();

  return (
    <div>
      <h1>Course: {courseId}</h1>
      <button onClick={() => navigate(-1)}>Back</button>
      <button onClick={() => navigate('/courses')}>All Courses</button>
    </div>
  );
}

import { memo, useCallback, useMemo } from 'react';

// React.memo: skip re-render if props haven't changed
const ExpensiveList = memo(function ExpensiveList({ items, onItemClick }) {
  console.log('Rendering ExpensiveList');
  return (
    <ul>
      {items.map(item => (
        <li key={item.id} onClick={() => onItemClick(item.id)}>
          {item.name}
        </li>
      ))}
    </ul>
  );
});

function Parent() {
  const [count, setCount] = useState(0);
  const [items] = useState([{id:1,name:'A'},{id:2,name:'B'}]);

  // Without useCallback, new function ref on every render
  // → ExpensiveList re-renders even though items didn't change
  const handleClick = useCallback((id) => {
    console.log('Clicked:', id);
  }, []); // stable reference

  return (
    <>
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>
      {/* Won't re-render when count changes — thanks to memo + useCallback */}
      <ExpensiveList items={items} onItemClick={handleClick} />
    </>
  );
}

import { Component, Suspense, lazy } from 'react';

// Error Boundary (must be a class component)
class ErrorBoundary extends Component {
  state = { hasError: false, error: null };

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, info) {
    console.error('Error caught:', error, info.componentStack);
    // Send to error tracking service (e.g., Sentry)
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback || (
        <div className="error-card">
          <h2>Something went wrong</h2>
          <button onClick={() => this.setState({ hasError: false })}>
            Try again
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

// Lazy loading with Suspense
const HeavyChart = lazy(() => import('./HeavyChart'));

function Dashboard() {
  return (
    <ErrorBoundary fallback={<p>Chart failed to load</p>}>
      <Suspense fallback={<Spinner />}>
        <HeavyChart />
      </Suspense>
    </ErrorBoundary>
  );
}

// Compound Components — API like <Select><Option /></Select>
const TabsContext = createContext(null);

function Tabs({ children, defaultTab }) {
  const [active, setActive] = useState(defaultTab);
  return (
    <TabsContext.Provider value={{ active, setActive }}>
      <div className="tabs">{children}</div>
    </TabsContext.Provider>
  );
}

function TabList({ children }) {
  return <div className="tab-list" role="tablist">{children}</div>;
}

function Tab({ id, children }) {
  const { active, setActive } = useContext(TabsContext);
  return (
    <button
      role="tab"
      aria-selected={active === id}
      onClick={() => setActive(id)}
    >
      {children}
    </button>
  );
}

function TabPanel({ id, children }) {
  const { active } = useContext(TabsContext);
  return active === id ? <div role="tabpanel">{children}</div> : null;
}

// Usage: clean, declarative, flexible
<Tabs defaultTab="react">
  <TabList>
    <Tab id="html">HTML</Tab>
    <Tab id="react">React</Tab>
  </TabList>
  <TabPanel id="html"><p>HTML content</p></TabPanel>
  <TabPanel id="react"><p>React content</p></TabPanel>
</Tabs>
